#pragma once
#include <string>

namespace amnezia::awgMigration {
// Canonical non-null lowercase UUID generated by the client's durable intent.
// This value is a causal nonce, never authority for executable payload bytes.
inline bool validClientOperationId(const std::string &value)
{
    if (value.size() != 36 || value == "00000000-0000-0000-0000-000000000000") return false;
    for (std::size_t i = 0; i < value.size(); ++i) {
        if (i == 8 || i == 13 || i == 18 || i == 23) {
            if (value[i] != '-') return false;
        } else if (!((value[i] >= '0' && value[i] <= '9') || (value[i] >= 'a' && value[i] <= 'f'))) return false;
    }
    return true;
}

inline std::string clientOperationOwner(const std::string &value)
{
    if (!validClientOperationId(value)) return {};
    std::string result;
    result.reserve(32);
    for (const char character : value) if (character != '-') result.push_back(character);
    return result;
}
} // namespace amnezia::awgMigration
